// Gera o bloco de agenda para injetar no system prompt da IA.
// Ligue este nó logo depois de "Consultar Horarios Livres".
let r = null;
try { r = $("Consultar Horarios Livres").first().json; } catch (e) { r = null; }
const list = (r && r.ok && Array.isArray(r.slotsLocal)) ? r.slotsLocal.slice(0, 6) : [];

let agendaBlock;
if (!list.length) {
  agendaBlock = "\n\n[AGENDA INDISPONÍVEL: não confirme nenhum horário agora; diga que vai verificar a agenda e retorna em instantes.]";
} else {
  agendaBlock = "\n\n=== AGENDA — HORÁRIOS REALMENTE LIVRES ===\n"
    + list.map((s, i) => (i + 1) + ") " + s).join("\n")
    + "\n\nREGRAS DE AGENDAMENTO (obrigatórias):\n"
    + "- Ofereça no máximo 2 opções por vez, priorizando 9h da manhã; use 14h só se o cliente não puder de manhã.\n"
    + "- NUNCA ofereça horário fora desta lista.\n"
    + "- NUNCA agende para hoje: mínimo 1 dia de antecedência.\n"
    + "- Ao fechar, escreva exatamente neste formato: \"Confirmado para <dia> às <hora>h\".\n"
    + "=== FIM AGENDA ===";
}

// Preserva tudo que veio do nó anterior e adiciona o campo agendaBlock.
const items = $input.all();
return items.map((item) => ({ json: { ...item.json, agendaBlock } }));
